// src/data/models.ts
// Unified machine-model catalog: technical specifications + the preset bill-of-materials
// (components/addons) for every model, across all machine families (mono/aba/3layer).
// Generated by scripts/merge-models.ts (see git history) from the previously-separate
// data/monoModels.ts, data/abaModels.ts, data/threeLayerModels.ts, and
// src/data/modelPresets.ts, then had stale dynamic-component size/price overrides
// stripped by scripts/strip-dynamic-sizes.ts so applyModelPreset()'s own sizing logic
// (based on each model's real layflatWidthMm) is the single source of truth.
// Motor-rating fields (extruderMotorRating, mainNipDrive, winderDrive,
// airRingBlowerRating) are uniformly in HP across all machine families — mono/ABA's
// original kW values were converted by scripts/convert-kw-to-hp.ts using the same
// standard motor table as src/utils/generateScopeDesc.js's kwToHp().

export type PresetComponent = {
  category: string;
  id: string;
  qty?: number;
  metadata?: any;
};

export type MachineModel = {
  // identity
  code: string;
  family?: string;
  label: string;
  machineType: "mono" | "aba" | "3layer" | "5layer";
  isIbc?: boolean;

  // technical specification fields (not every family populates every field) — all
  // motor/drive ratings are in HP.
  screwDiameter?: string;
  screwLdRatio?: string;
  extruderMotorRating?: string;
  dieSizeHmLd?: string;
  airRingBlowerRating?: string;
  layflatWidthMm?: number;
  thicknessRange?: string;
  thicknessVariation?: string;
  maxOutputKgHr?: string;
  mainNipDrive?: string;
  mainNipLineSpeed?: string;
  winderType?: string;
  winderDrive?: string;
  totalConnectedLoadKw?: string;
  totalHeatingLoadKw?: string;
  specificPowerConsumption?: string;
  overallDimensions?: string;

  // 3-layer-only concepts
  bubbleCage?: string;
  collapsingFrame?: string;
  additionalNip?: string;
  trimBlower?: string;
  rollCapacity?: string;
  controlPanel?: string;
  tensionControl?: string;

  // preset payload: fixed pricing + the bill-of-materials auto-applied on selection
  basePrice?: number;
  components: PresetComponent[];
  addons?: PresetComponent[];
};

